1	import { describe, it, expect } from 'vitest';
2	import { EditorState } from '@codemirror/state';
3	import { EditorView } from '@codemirror/view';
4	import { markdown } from '@codemirror/lang-markdown';
5	import { Table } from '@lezer/markdown';
6	import { tableField } from '../table';
7	import { mouseSelectingField } from '../../core/mouseSelecting';
8	import { collapseOnSelectionFacet } from '../../core/facets';
9	
10	describe('tableField', () => {
11	  function createTestView(doc: string, cursorPos?: number) {
12	    const state = EditorState.create({
13	      doc,
14	      selection: cursorPos !== undefined ? { anchor: cursorPos } : undefined,
15	      extensions: [
16	        markdown({ extensions: [Table] }),
17	        mouseSelectingField,
18	        collapseOnSelectionFacet.of(true),
19	        tableField,
20	      ],
21	    });
22	    const container = document.createElement('div');
23	    return new EditorView({ state, parent: container });
24	  }
25	
26	  const simpleTable = `| Name | Age |
27	|------|-----|
28	| Alice | 25 |`;
29	
30	  const tableWithText = `Some text before
31	
32	| Name | Age |
33	|------|-----|
34	| Alice | 25 |
35	
36	Some text after`;
37	
38	  it('should initialize without errors', () => {
39	    const view = createTestView(simpleTable);
40	    const decos = view.state.field(tableField);
41	
42	    expect(decos).toBeDefined();
43	
44	    view.destroy();
45	  });
46	
47	  it('should handle empty document', () => {
48	    const view = createTestView('');
49	    const decos = view.state.field(tableField);
50	
51	    expect(decos.size).toBe(0);
52	
53	    view.destroy();
54	  });
55	
56	  it('should handle document without table', () => {
57	    const view = createTestView('Just plain text\n\nNo tables here');
58	    const decos = view.state.field(tableField);
59	
60	    expect(decos.size).toBe(0);
61	
62	    view.destroy();
63	  });
64	
65	  it('should detect table in document', () => {
66	    const view = createTestView(simpleTable);
67	    const decos = view.state.field(tableField);
68	
69	    // 应该有装饰
70	    expect(decos.size).toBeGreaterThan(0);
71	
72	    view.destroy();
73	  });
74	
75	  it('should show widget when cursor outside table', () => {
76	    // 光标在表格之后
77	    const view = createTestView(tableWithText, tableWithText.length);
78	    const decos = view.state.field(tableField);
79	
80	    let hasWidget = false;
81	    decos.between(0, view.state.doc.length, (_from, _to, deco) => {
82	      const spec = deco.spec as { widget?: unknown };
83	      if (spec.widget) {
84	        hasWidget = true;
85	      }
86	    });
87	
88	    expect(hasWidget).toBe(true);
89	
90	    view.destroy();
91	  });
92	
93	  it('should show source when cursor inside table', () => {
94	    // 光标在表格内部（第一行）
95	    const view = createTestView(simpleTable, 5);
96	    const decos = view.state.field(tableField);
97	
98	    let hasSourceClass = false;
99	    decos.between(0, view.state.doc.length, (_from, _to, deco) => {
100	      const spec = deco.spec as { class?: string };
101	      if (spec.class?.includes('cm-table-source')) {
102	        hasSourceClass = true;
103	      }
104	    });
105	
106	    expect(hasSourceClass).toBe(true);
107	
108	    view.destroy();
109	  });
110	
111	  it('should update on document change', () => {
112	    const view = createTestView('plain text');
113	
114	    view.dispatch({
115	      changes: { from: 0, to: 10, insert: simpleTable },
116	    });
117	
118	    const decos = view.state.field(tableField);
119	    expect(decos.size).toBeGreaterThan(0);
120	
121	    view.destroy();
122	  });
123	
124	  it('should update on selection change', () => {
125	    // 光标初始在表格外
126	    const view = createTestView(tableWithText, tableWithText.length);
127	
128	    // 移动光标到表格内部
129	    view.dispatch({
130	      selection: { anchor: 20 },
131	    });
132	
133	    const decos = view.state.field(tableField);
134	    expect(decos).toBeDefined();
135	
136	    view.destroy();
137	  });
138	
139	  it('should handle multiple tables', () => {
140	    const doc = `${simpleTable}
141	
142	Some text in between the tables
143	
144	| A | B |
145	|---|---|
146	| 1 | 2 |
147	
148	More text after`;
149	
150	    // 光标在中间文本处，不触及任何表格
151	    const view = createTestView(doc, 50);
152	    const decos = view.state.field(tableField);
153	
154	    // 应该有多个装饰（两个表格）
155	    let widgetCount = 0;
156	    decos.between(0, view.state.doc.length, (_from, _to, deco) => {
157	      const spec = deco.spec as { widget?: unknown };
158	      if (spec.widget) {
159	        widgetCount++;
160	      }
161	    });
162	
163	    expect(widgetCount).toBe(2);
164	
165	    view.destroy();
166	  });
167	
168	  it('should handle invalid table syntax', () => {
169	    // 无效表格（没有分隔行）
170	    const invalidTable = `| A | B |
171	| 1 | 2 |`;
172	
173	    const view = createTestView(invalidTable);
174	    const decos = view.state.field(tableField);
175	
176	    // 无效表格不应该有装饰
177	    let hasTableDeco = false;
178	    decos.between(0, view.state.doc.length, (_from, _to, deco) => {
